function updateMusicTimeUI() {
  // 시진 버튼 active
  for(var i=0;i<12;i++) {
    var btn = document.getElementById('msjBtn'+i);
    if(btn) btn.classList.toggle('active', i===_musicSiJin);
  }
  // 계절 버튼 active
  ['봄','여름','가을','겨울'].forEach(function(s){
    var btn = document.getElementById('mssBtn'+s);
    if(btn) btn.classList.toggle('active', s===_musicSeason);
  });
  // 현재 시간 표시
  var timeEl = document.getElementById('musicCurrentTime');
  if(timeEl) {
    var now = new Date();
    timeEl.textContent = now.toLocaleTimeString(window._cgoLocale(),{hour:'2-digit',minute:'2-digit',second:'2-digit'});
  }
  // 시진 설명
  var descEl = document.getElementById('musicContextDesc');
  if(descEl && SIJIN_DATA[_musicSiJin]) {
    var sd = SIJIN_DATA[_musicSiJin];
    var p = window._nasaPlanets;
    var nasaNote = p ? ('🛰️ NASA: 목성(' + p.jupiter.zodiac.sign + ') '+(p.jupiter.retro?'역행':'순행')) : '';
    descEl.innerHTML = '<strong style="color:var(--gold)">' + sd.emoji + ' ' + sd.name + '</strong> — '
      + sd.desc
      + (nasaNote ? '<br><span style="color:#34d399;font-size:10px">' + nasaNote + ' · 계절: '+_musicSeason+'</span>' : '');
  }
  // 현재 시진 버튼 강조
  var autoSj = getCurrentSiJin();
  for(var j=0;j<12;j++){
    var b2 = document.getElementById('msjBtn'+j);
    if(b2) b2.style.boxShadow = (j===autoSj && j===_musicSiJin) ? '0 0 8px rgba(52,211,153,.4)' : '';
  }
};

function _getMusicOh(){
  if(window._pajR&&window._pajR.domOh) return window._pajR.domOh;
  if(window.calcResult&&window.calcResult.domOh) return window.calcResult.domOh;
  // BS 데이터로 폴백
  var bpm=(typeof BS!=='undefined'&&BS.bpm)||72;
  var ohs=['목','화','토','금','수'];
  return ohs[bpm%5];
};

function getCurrentSiJin() {
  var h = new Date().getHours();
  if(h===23||h===0) return 0;  // 자시
  return Math.floor((h+1)/2);
};

function getCurrentSeason() {
  var m = (window._fcBase||new Date()).getMonth()+1;
  if(m>=3&&m<=5)  return '봄';
  if(m>=6&&m<=8)  return '여름';
  if(m>=9&&m<=11) return '가을';
  return '겨울';
};

function analyze(cv){
    var ow=120, oh2=Math.round(120*cv.height/cv.width);
    var off=document.createElement('canvas'); off.width=ow; off.height=oh2;
    var octx=off.getContext('2d',{willReadFrequently:true}); octx.drawImage(cv,0,0,ow,oh2);
    var data=octx.getImageData(0,0,ow,oh2).data;
    var w={목:0,화:0,토:0,금:0,수:0}, tot=0;
    for(var i=0;i<data.length;i+=4){
      var r=data[i]/255, g=data[i+1]/255, b=data[i+2]/255;
      var mx=Math.max(r,g,b), mn=Math.min(r,g,b), L=(mx+mn)/2, d=mx-mn;
      var sat=d===0?0:(L>0.5?d/(2-mx-mn):d/(mx+mn));
      var hue=0;
      if(d!==0){ if(mx===r) hue=((g-b)/d)%6; else if(mx===g) hue=(b-r)/d+2; else hue=(r-g)/d+4; hue*=60; if(hue<0)hue+=360; }
      var oh;
      if(L>0.82 && sat<0.16) oh='금';            // 밝고 무채색 → 백(금)
      else if(L<0.18) oh='수';                    // 매우 어두움 → 흑(수)
      else if(hue<35||hue>=330) oh='화';          // 적 → 화
      else if(hue<70) oh='토';                    // 황 → 토
      else if(hue<170) oh='목';                   // 청록 → 목
      else if(hue<260) oh='수';                   // 청 → 수
      else oh='화';                               // 자주 → 화 경향
      var wt=0.4+sat*0.6;                          // 선명할수록 가중
      w[oh]+=wt; tot+=wt;
    }
    var pct={}; for(var k=0;k<OHK.length;k++){ pct[OHK[k]]=tot>0?w[OHK[k]]/tot:0; }
    // 정수 % (합 100)
    var arr=OHK.map(function(o){return {o:o, p:Math.round(pct[o]*100)};});
    var acc=arr.reduce(function(a,x){return a+x.p;},0); arr[0].p+=100-acc;
    arr.sort(function(a,b){return b.p-a.p;});
    var dom=arr[0].o;
    return { dist:arr, dom:dom };
  };

