function _cgoForceStopAllMedia(){
  try {
    // 1) 페이지 안 모든 video/audio 요소의 srcObject track 강제 해제
    var els = document.querySelectorAll('video, audio');
    for(var i=0;i<els.length;i++){
      var el = els[i];
      if(el.srcObject && el.srcObject.getTracks){
        el.srcObject.getTracks().forEach(function(t){ try{t.stop();}catch(e){} });
        el.srcObject = null;
      }
    }
    // 2) window 전역에 알려진 stream 변수도 모두 해제
    var globals = ['_trv2ScanStream','_trv2Mic','_breathMicStream','TVY_CAM','_cgoMediaStream'];
    for(var j=0;j<globals.length;j++){
      var g = window[globals[j]];
      if(g){
        var s = g.stream || g;
        if(s && s.getTracks){
          try{ s.getTracks().forEach(function(t){ try{t.stop();}catch(e){} }); }catch(e){}
        }
      }
    }
  } catch(e){ /* 안전: 어떤 오류도 사용자 흐름 막지 않음 */ }
};

function cgoLaunchRppg(){
  window._cgoInRealtimeMode=true;window._cgoInPureMode=false; try{ window.cgoTfHead && cgoTfHead('rppg'); }catch(e){}
  _cgoRestoreEngineMode('rppg');
  var ov=document.getElementById('todayFortuneOverlay');
  if(ov){ov.style.display='block';document.body.style.overflow='hidden';}
  setTimeout(function(){
    var h=document.getElementById('tf-overlay-title');
    if(h){h.textContent=_cgoT('🛰️ 실시간 rPPG 데이터 연동 분석');h.style.color='#059669';}
    var rp=document.getElementById('tf-rppg-card');if(rp)rp.style.display='block';var rc=document.getElementById('tf-realtime-card');if(rc)rc.style.display='block';var bc=document.getElementById('tf-bio-card');if(bc)bc.style.display='none';var rts=document.getElementById('tf-rt-result');if(rts)rts.style.display='none';var ld=document.getElementById('tf-loading');if(ld)ld.style.display='none';
    var rs=document.getElementById('tf-result');if(rs)rs.style.display='none';
    // ★ 핵심: 체크 상태 sessionStorage에서 복원
    ['face','palm','tongue','breath'].forEach(function(t){
      try{
        // sessionStorage 체크
        var done = sessionStorage.getItem('_cgoRppgDone_'+t);
        // bioSkinData 체크
        var bsd = window._bioSkinData || {};
        var bfd = window._bioFinalData || {};
        var HV  = window._HV || {};
        var isDone = done
          || (t==='face'   && bfd.fci > 0)
          || (t==='palm'   && bfd.bli > 0)
          || (t==='tongue' && (bsd.tongue && bsd.tongue.color || bfd.tongueDone || HV.tDone))
          || (t==='breath' && HV.bDone === true);
        var ce = document.getElementById('rppg-check-'+t);
        if(ce) ce.style.display = isDone ? 'inline' : 'none';
      }catch(e){}
    });
  },100);
  if(typeof cgoOpenTodayFortune==='function')cgoOpenTodayFortune();
};

function qtShowLoading(){
  var box=document.getElementById('qt-chat-messages'); if(!box) return null;
  var d=document.createElement('div'); d.id='qt-load';
  d.style.cssText='display:flex;gap:8px;align-items:center;';
  d.innerHTML='<div style="width:28px;height:28px;border-radius:50%;background:rgba(139,92,246,.3);display:flex;align-items:center;justify-content:center;">🔮</div>'+
    '<div style="padding:9px 13px;background:rgba(139,92,246,.1);border:1px solid rgba(139,92,246,.25);border-radius:4px 12px 12px 12px;font-size:12px;color:rgba(139,92,246,.6);" id="qt-dot-wrap">분석 중<span id="qt-dots">.</span></div>';
  box.appendChild(d); box.scrollTop=box.scrollHeight;
  var dots=document.getElementById('qt-dots');
  var ti=setInterval(function(){if(!document.getElementById('qt-load')){clearInterval(ti);return;}dots.textContent=dots.textContent.length>=3?'.':dots.textContent+'.';},400);
  return d;
};

function qtAddMsg(role,text){
  var box=document.getElementById('qt-chat-messages'); if(!box) return;
  var isAI=role==='ai';
  var d=document.createElement('div');
  d.style.cssText='display:flex;gap:8px;align-items:flex-start;'+(isAI?'':'flex-direction:row-reverse;');
  d.innerHTML='<div style="width:28px;height:28px;border-radius:50%;background:'+(isAI?'rgba(139,92,246,.3)':'rgba(212,168,67,.2)')+';display:flex;align-items:center;justify-content:center;font-size:13px;flex-shrink:0;">'+(isAI?'🔮':'👤')+'</div>'+
    '<div style="max-width:82%;padding:9px 13px;background:'+(isAI?'rgba(139,92,246,.1)':'rgba(212,168,67,.1)')+';border:1px solid '+(isAI?'rgba(139,92,246,.25)':'rgba(212,168,67,.25)')+';border-radius:'+(isAI?'4px 12px 12px 12px':'12px 4px 12px 12px')+';font-size:12px;color:#1f2937;line-height:1.75;">'+text+'</div>';
  box.appendChild(d);
  box.scrollTop=box.scrollHeight;
  _qt.chatHistory.push({role:isAI?'assistant':'user',content:text.replace(/<[^>]*>/g,'')});
};

