function shopRenderGrid(cat){
  var g=document.getElementById('shopGrid'); if(!g)return;
  g.innerHTML=''; // ← 핵심 수정: 기존 내용 초기화
  var items=cat==='all'?SHOP_ITEMS:SHOP_ITEMS.filter(function(i){return i.cat===cat;});
  var oh=window._sOh||'목';
  var rgb={목:'52,211,153',화:'248,113,113',토:'251,191,36',금:'226,232,240',수:'56,189,248'};
  var html='';
  items.forEach(function(it){
    var cardOh=it.cat==='custom'?'화':oh;
    var bg='rgba('+(it.cat==='custom'?'248,113,113':rgb[oh]||'212,168,67')+',.05)';
    var badgeHtml='';
    if(it.badge){
      var bc=it.badge==='new'?'52,211,153':it.badge==='hot'?'251,191,36':'248,113,113';
      var bcolor=it.badge==='new'?'#34d399':it.badge==='hot'?'#fbbf24':'#f87171';
      var btxt=it.badge==='new'?'NEW':it.badge==='hot'?'인기':'맞춤';
      badgeHtml='<span style="position:absolute;top:8px;left:8px;padding:2px 7px;border-radius:7px;font-size:9px;font-weight:700;z-index:2;background:rgba('+bc+',.25);color:'+bcolor+'">'+btxt+'</span>';
    }
    var svgImg=_shopTalismanSvg(cardOh,it.emoji);
    var card=document.createElement('div');
    card.style.cssText='background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.08);border-radius:14px;overflow:hidden;cursor:pointer;transition:all .25s;';
    card.addEventListener('mouseenter',function(){this.style.borderColor='rgba(212,168,67,.35)';this.style.transform='translateY(-2px)';});
    card.addEventListener('mouseleave',function(){this.style.borderColor='rgba(255,255,255,.08)';this.style.transform='';});
    card.addEventListener('click',(function(id){return function(){shopOpenPop(id);};})(it.id));
    card.innerHTML='<div style="width:100%;aspect-ratio:1;position:relative;background:'+bg+';overflow:hidden;">'+svgImg+badgeHtml+'</div>'
      +'<div style="padding:10px 10px 12px;">'
        +'<div style="font-size:12px;font-weight:700;color:#e2e8f0;margin-bottom:2px;">'+it.name+'</div>'
        +'<div style="font-size:10px;color:rgba(240,230,200,0.8);margin-bottom:6px;">'+it.sub+'</div>'
        +'<div style="display:flex;align-items:center;justify-content:space-between;">'
          +'<div style="font-size:14px;font-weight:800;color:#d4a843;">준비중</div>'
          +'<div style="width:28px;height:28px;border-radius:8px;background:rgba(212,168,67,.15);border:1px solid rgba(212,168,67,.3);color:#d4a843;display:flex;align-items:center;justify-content:center;font-size:13px;cursor:pointer;">🛒</div>'
        +'</div>'
      +'</div>';
    card.querySelector('div:last-child div:last-child div:last-child').addEventListener('click',(function(id){return function(e){e.stopPropagation();shopAddCart(id);};})(it.id));
    g.appendChild(card);
  });
};

function stripKo(c){
    if(typeof c!=='string') return c;
    c=c.replace(/[^.]*한국어로만[^.]*\./g,' ');
    c=c.replace(/반드시[^.]*100%[^.]*한국어[^.]*\./g,' ');
    c=c.replace(/furthermore[^.]*?금지\.?/gi,' ');
    c=c.replace(/영어\s*단어\s*절대\s*사용\s*금지\.?/g,' ');
    /* C-66: 마침표 없는 한국어 강제 라인·구문 변형까지 제거 (구문 단위 — 같은 줄의 다른 규칙은 보존) */
    c=c.replace(/순수한?\s*한국어(?:로만|로|만)?[^.\n,]*[.,]?/g,' ');
    c=c.replace(/(?:반드시\s*)?(?:100%\s*)?한국어(?:로만|만|로)\s*(?:답변|답하|작성|사용|쓰)[^.\n,]*[.,]?/g,' ');
    c=c.replace(/한글로만[^.\n,]*[.,]?/g,' ');
    c=c.replace(/순수\s*한글만[^.\n,]*[.,]?/g,' ');
    c=c.replace(/외국어\s*(?:절대\s*)?(?:단어\s*)?(?:사용\s*)?금지\.?/g,' ');
    c=c.replace(/한국어만\s*[,.]?/g,' ');
    return c;
  };

function cgoTfCheckEngine(id,val){
  _tfSelected[id]=val;
  if(_cgoActiveMode==='realtime') _tfSelectedRealtime[id]=val;
  else if(_cgoActiveMode==='rppg') _tfSelectedRppg[id]=val;
  else _tfSelectedPure[id]=val;
  cgoTfUpdateCount();
  cgoTfUpdateWeight();
  // ★ C-35 헌법 v3.0 §V.5.1 정직 적용: 결과 화면이 이미 떠있으면 자동 재분석
  // 大將 의심 해결 — "체크박스 바꿔도 점수 똑같은" 위배 정리
  _cgoTfAutoReanalyze();
};

function cgoTfUpdateCount(){
  var cnt=Object.values(_tfSelected).filter(Boolean).length;
  var el=document.getElementById('tf-selected-count');
  if(el) el.textContent=_cgoTV(('('+cnt+'개 선택됨)'),('('+cnt+' selected)'));
};
