window._cgoTX = function(ko, en){
  try{
    var L = (window._cgoKeyLang ? window._cgoKeyLang() : window._LANG) || 'en';
    if(L === 'ko') return ko;
    if(typeof _cgoT === 'function'){
      var v = _cgoT(ko);
      if(v && v !== ko && !/[\uac00-\ud7a3]/.test(v)) return v;
    }
    return (en !== undefined && en !== null && en !== '') ? en : ko;
  }catch(e){ return en || ko; }
};
var _cgoTX = window._cgoTX;

