function _cgoAutoFillAll() {
  try {
    // ── 대시보드 소스 값 읽기 ──
    var ipNameEl = document.getElementById('ipName');
    var ipBirthY = document.getElementById('ipBirthY');
    var ipBirthM = document.getElementById('ipBirthM');
    var ipBirthD = document.getElementById('ipBirthD');
    var ipBirth  = document.getElementById('ipBirth');
    var ipTime   = document.getElementById('ipTime');
    var ipGender = document.getElementById('ipGender');
    var ipCalType = document.getElementById('ipCalType');

    var name    = ipNameEl ? (ipNameEl.value || '').trim() : '';
    var birthY  = ipBirthY ? (ipBirthY.value || '').trim() : '';
    var birthM  = ipBirthM ? (ipBirthM.value || '').trim() : '';
    var birthD  = ipBirthD ? (ipBirthD.value || '').trim() : '';
    var birthH  = ipBirth  ? (ipBirth.value  || '').trim() : '';
    var time    = ipTime   ? (ipTime.value   || '').trim() : '';
    var gender  = ipGender ? (ipGender.value || '').trim() : '';
    var calType = ipCalType ? (ipCalType.value || 'solar') : 'solar';

    // 대시보드 값 자체가 없으면 종료
    if (!name && !birthY) return;

    // ── 헬퍼: 빈 필드만 채움 ──
    function fillIfEmpty(id, val) {
      var el = document.getElementById(id);
      if (!el || !val) return;
      var current = (el.value || '').trim();
      if (current === '') {
        el.value = val;
        // input 이벤트 트리거 → 다른 sync 함수 작동
        try {
          el.dispatchEvent(new Event('input', {bubbles:true}));
          el.dispatchEvent(new Event('change', {bubbles:true}));
        } catch(e) {}
      }
    }

    // ──────────────────────────────────────
    // 🎰 행운 번호 페이지
    // ──────────────────────────────────────
    /* ★ 키·몸무게 되돌리기 — 눈 검사의 자, 오행 의류의 치수로 쓰인다 */
  try{
    var _si2 = JSON.parse(localStorage.getItem('cgo_saved_info')||'{}');
    if(_si2.height) fillIfEmpty('ipHeight', _si2.height);
    if(_si2.weight) fillIfEmpty('ipWeight', _si2.weight);
  }catch(_e){}

  fillIfEmpty('ltBirthY', birthY);
    fillIfEmpty('ltBirthM', birthM);
    fillIfEmpty('ltBirthD', birthD);
    fillIfEmpty('ltBirth',  birthH);

    // ──────────────────────────────────────
    // ✍️ 작명 페이지
    // ──────────────────────────────────────
    fillIfEmpty('nmBirthY', birthY);
    fillIfEmpty('nmBirthM', birthM);
    fillIfEmpty('nmBirthD', birthD);
    fillIfEmpty('nmBirth',  birthH);
    fillIfEmpty('nmGender', gender);

    // ──────────────────────────────────────
    // 💑 커플 궁합 — A(나)만 자동, B(상대)는 사용자 입력 보존
    // ──────────────────────────────────────
    fillIfEmpty('cpl-a-name', name);
    fillIfEmpty('cpl-a-y', birthY);
    fillIfEmpty('cpl-a-m', birthM);
    fillIfEmpty('cpl-a-d', birthD);
    fillIfEmpty('cpl-a-time', time);
    // 달력 타입(양/음) — solar→양, lunar→음
    var calA = document.getElementById('cpl-a-cal');
    if (calA && (calA.value === '' || calA.value === '양')) {
      calA.value = (calType === 'lunar' ? '음' : '양');
    }
    // 성별 — A
    var genderA = document.getElementById('cpl-a-gender');
    if (genderA && !genderA.value && gender) genderA.value = gender;

    // ──────────────────────────────────────
    // 🍱 음식 페이지 — 체질 오행 자동 (calcResult에서)
    // ──────────────────────────────────────
    var fpConst = document.getElementById('fp-constitution');
    if (fpConst && !fpConst.value) {
      var domOh = '';
      if (typeof calcResult !== 'undefined' && calcResult && calcResult.domOh) {
        domOh = calcResult.domOh;
      } else if (window.calcResult && window.calcResult.domOh) {
        domOh = window.calcResult.domOh;
      }
      if (domOh) {
        fpConst.value = domOh;
        // 체질 오행 버튼도 활성 표시 (foodSetOh 호출)
        try {
          var ohBtns = document.querySelectorAll('.fp-oh-btn');
          ohBtns.forEach(function(btn){
            var txt = (btn.textContent || '').trim();
            if (txt.indexOf(domOh) >= 0 && typeof foodSetOh === 'function') {
              foodSetOh(btn, domOh);
            }
          });
        } catch(e) {}
      }
    }

    // ──────────────────────────────────────
    // 🔍 행운 번호 - 내 번호 분석 (스마트폰)는 사용자 입력
    // ──────────────────────────────────────
    // (전화번호는 자동 안 함 — 개인 선택)

  } catch(e) {
    // 전역 자동 채우기는 *조용히* 실패 (UX 우선)
    if (window.console) console.warn('[_cgoAutoFillAll]', e.message);
  }
};

