function _syncBioUI() {
  var d = window._bioFinalData;
  if (!d) return;

  // ① 대시보드 생체 스킨 분석 (bm-* / bf-*)
  var bmMap={'bm-hrv':d.hrv,'bm-fci':d.fci,'bm-fma':d.fma,'bm-bli':d.bli};
  Object.keys(bmMap).forEach(function(id){
    var el=document.getElementById(id);
    if(el&&bmMap[id]>0) el.textContent=bmMap[id];
  });
  var bfMap={'bf-hrv':d.hrv,'bf-fci':d.fci,'bf-fma':d.fma,'bf-bli':d.bli};
  Object.keys(bfMap).forEach(function(id){
    var el=document.getElementById(id);
    if(el&&bfMap[id]>0) el.style.width=Math.min(100,bfMap[id])+'%';
  });

  // ② 스캔 페이지 HRV/FCI 수치+바 (bsHrvVal / bsFciVal)
  if(d.hrv>0){
    var hv=document.getElementById('bsHrvVal'); if(hv) hv.textContent=d.hrv;
    var hb=document.getElementById('bsHrvBar'); if(hb) hb.style.width=Math.min(100,d.hrv)+'%';
  }
  if(d.fci>0){
    var fc=document.getElementById('bsFciVal'); if(fc) fc.textContent=d.fci;
    var fb=document.getElementById('bsFciBar'); if(fb) fb.style.width=Math.min(100,d.fci)+'%';
  }

  // ③ 자동계산 후 통합 라이프 인덱스 BAI 패널 (ili-bai-*)
  var iliMap={'ili-bai-hrv':d.hrv,'ili-bai-fci':d.fci,'ili-bai-fma':d.fma,'ili-bai-bli':d.bli};
  Object.keys(iliMap).forEach(function(id){
    var el=document.getElementById(id);
    if(el&&iliMap[id]>0) el.textContent=iliMap[id];
  });

  // ④ appState.bio 동기화
  if(!window.appState) window.appState={};
  if(!window.appState.bio) window.appState.bio={};
  if(d.hrv>0) window.appState.bio.hrv=d.hrv;
  if(d.fci>0) window.appState.bio.fci=d.fci;
  if(d.fma>0) window.appState.bio.fma=d.fma;
  if(d.bli>0) window.appState.bio.bli=d.bli;
  if(d.bpm>0) window.appState.bio.bpm=d.bpm;

  // ⑤ ★ 대시보드 BAI 카드 직접 업데이트
  var dashHrv=document.getElementById('dash-hrv-num');
  var dashFci=document.getElementById('dash-fci-num');
  var dashFma=document.getElementById('dash-fma-num');
  var dashBli=document.getElementById('dash-bli-num');
  if(dashHrv&&d.hrv>0) dashHrv.textContent=d.hrv;
  if(dashFci&&d.fci>0) dashFci.textContent=d.fci;
  if(dashFma&&d.fma>0) dashFma.textContent=d.fma;
  if(dashBli&&d.bli>0) dashBli.textContent=d.bli;

  // ⑤ BS 객체 동기화
  if(window.BS){
    if(d.hrv>0) BS.hrv=d.hrv;
    if(d.fci>0) BS.fci=d.fci;
    if(d.bpm>0) BS.bpm=d.bpm;
    if(d.eng>0) BS.eng=d.eng;
  }

  // ⑥ _HV 동기화
  if(window._HV){
    if(d.faceScore>0) _HV.v4=d.faceScore;
    if(d.palmScore>0) _HV.v5=d.palmScore;
    if(d.hrv>0) _HV.bScore=d.hrv;
  }

  // ⑦ 건강 페이지 생체 카드 (hlt-bio-face/palm/tongue-score) 동기화
  // 혀 데이터 tongueDone → _bioSkinData 복원
  if(d.tongueDone && d.tongueColor && (!window._bioSkinData || !window._bioSkinData.tongue)){
    if(!window._bioSkinData) window._bioSkinData={};
    window._bioSkinData.tongue={color:d.tongueColor,organ:d.tongueOrgan||'그라운딩 에너지',energy:d.tongueEnergy||70};
  }
  if(typeof hltSyncBioCards==='function') hltSyncBioCards();

  // ⑧ ★ 생체 스캔 완료 시 bio-locked 카드 잠금 해제
  // rPPG 카드(ID 있음) 제외, 시진별 운세 등 class만 있는 카드 해제
  var hasBio = (d.fci>0 || d.hrv>0 || (window._bioSkinData && window._bioSkinData.tongue));
  if(hasBio || window._baiScanned){
    document.querySelectorAll('.bio-locked').forEach(function(el){
      el.classList.remove('bio-locked');
      el.style.opacity = '1';
      el.style.pointerEvents = 'auto';
    });
    // rPPG 카드도 활성화 (CGO FULI 생체 완료 시)
    var rppgEl = document.getElementById('rppg-card');
    if(rppgEl){
      rppgEl.classList.remove('bio-locked');
      rppgEl.style.opacity='1';
      rppgEl.style.pointerEvents='auto';
    }
  }

  // ⑨ ★ 대시보드 ILI 카드 → CEI 신버전으로 업그레이드 표시
  if(typeof _cgoGetScore === 'function'){
    var s = _cgoGetScore();
    // 점수 숫자 (CEI or ILI)
    var iliNumEl = document.getElementById('dash-ili-num');
    if(iliNumEl) iliNumEl.textContent = s.score;
    // 바
    var iliBarEl = document.getElementById('dash-ili-bar');
    if(iliBarEl) iliBarEl.style.width = s.score + '%';
    // 등급
    var iliGrEl = document.getElementById('dash-ili-grade');
    if(iliGrEl){
      iliGrEl.textContent = s.grade + ' — ' + s.gradeMsg;
      iliGrEl.style.color = s.color;
      iliGrEl.style.borderColor = s.color + '55';
      iliGrEl.style.background = s.color + '18';
    }
    // 스캔 완료 시: CEI 뱃지 + 라벨 + 점수 구성 설명 표시
    if(s.scanned){
      var badge = document.getElementById('dash-cei-badge');
      if(badge) badge.style.display = 'block';
      var lbl = document.getElementById('dash-score-label');
      if(lbl){ lbl.textContent = 'CEI'; lbl.style.color = '#34d399'; }
      var sub = document.getElementById('dash-score-sublabel');
      if(sub) sub.textContent = _cgoT('생체×역학×공명 통합 에너지 지수');
      var brk = document.getElementById('dash-score-breakdown');
      if(brk){ brk.style.display = 'block'; brk.textContent = s.breakdown; }
      // 바 색상도 초록으로 변경
      if(iliBarEl) iliBarEl.style.background = 'linear-gradient(90deg,#34d399,#38bdf8)';
    }
  }
};

