function _cgoVisionStartCam(){
  // ★ C-35 — 권한 체크 제거 (cgoCameraCheck가 별도 권한 팝업 띄워서 2번 떴음)
  // 다른 페이지 7곳은 cgoCameraCheck 유지, 관상만 직접 호출
  /* ★ C-63: 미가입(guest)이면 카메라 화면을 열지 않고 닫은 뒤 가입유도만 (권한요청·잔여 오버레이 방지) */
  try{ if(typeof _cgoTier==='function' && _cgoTier()==='guest'){ if(typeof _cgoVisionClose==='function') _cgoVisionClose(); if(typeof _cgoSignupPrompt==='function') _cgoSignupPrompt('실시간 측정'); return; } }catch(e){}
  _cgoVisionStartCamCore();
};

function _cgoGetScore() {

  // ── 1. 기초 데이터 수집 ──────────────────────────────────
  var M   = window._CGO_MASTER || null;
  var bfd = window._bioFinalData || {};
  var cr  = window.calcResult || {};

  // ILI: 역학 점수 (계산 안 됐으면 70 기본값)
  var ili = (M && M.ili > 0) ? M.ili : (cr.ili || 70);

  // 스캔 여부 확인 (얼굴·손금·혀 중 하나라도 실측되면 true)
  var scanned = !!(window._baiScanned
    || (bfd.fci > 0)
    || (bfd.hrv > 0)
    || (bfd.bli > 0)
    || (window._bioSkinData && window._bioSkinData.tongue));

  // ── 2. BAI 계산 (생체활성도 0~100) ──────────────────────
  var bai = 0;
  if (scanned) {
    var parts = [];

    // ① 심박수 BPM — 정상(60~80)이면 높은 점수
    var bpm = bfd.bpm || (window.BS && window.BS.bpm) || 0;
    if (bpm > 0) {
      var bpmS = (bpm >= 60 && bpm <= 80) ? 90
               : (bpm >= 50 && bpm <= 95) ? 75 : 60;
      parts.push(bpmS);
    }

    // ② HRV 심박변이도 — 높을수록 자율신경 안정
    var hrv = bfd.hrv || 0;
    if (hrv > 0) {
      var hrvS = hrv > 55 ? 92 : hrv > 40 ? 78 : hrv > 25 ? 65 : 52;
      parts.push(hrvS);
    }

    // ③ FCI 안면혈색지수 — 혈류가 좋을수록 높은 점수
    var fci = bfd.fci || 0;
    if (fci > 0) {
      var fciS = fci > 80 ? 90 : fci > 65 ? 78 : fci > 50 ? 65 : 52;
      parts.push(fciS);
    }

    // ④ BLI 손금생명지수
    var bli = bfd.bli || 0;
    if (bli > 0) parts.push(Math.min(95, Math.max(40, bli)));

    // ⑤ TLI 혀건강지수
    var tli = (window.BS && window.BS.tongueData)
            ? (window.BS.tongueData.tliScore || 0) : 0;
    if (tli > 0) parts.push(Math.min(95, Math.max(40, tli)));

    bai = parts.length > 0
      ? Math.round(parts.reduce(function(s, v){ return s + v; }, 0) / parts.length)
      : Math.round(ili * 0.85);
  }

  // ── 3. CEI 계산 (통합에너지지수) ─────────────────────────
  var cei = ili; // 기본값: 스캔 전이면 ILI 그대로
  var resonanceScore = ili; // 공명 점수 기본값

  if (scanned) {
    // 공명 점수: ILI + NASA·날씨·방위 보너스
    var resBonus = window._cgoLastResonanceBonus || 0;
    resonanceScore = Math.min(99, ili + resBonus);

    // ★ 핵심 공식: BAI×40% + ILI×35% + 공명×25%
    var raw = Math.round(bai * 0.40 + ili * 0.35 + resonanceScore * 0.25);
    cei = Math.min(99, Math.max(40, raw));
  }

  // ── 4. 최종 점수 결정 ────────────────────────────────────
  var score = scanned ? cei : ili;

  // ── 5. 등급 계산 ─────────────────────────────────────────
  var grade, gradeMsg, color;
  if (score >= 90) {
    grade = 'S+'; gradeMsg = '최상의 에너지 상태 — 오늘은 무엇이든 됩니다';
    color = '#fbbf24'; // 금색
  } else if (score >= 80) {
    grade = 'A';  gradeMsg = '에너지 충만 — 적극적으로 움직이세요';
    color = '#34d399'; // 초록
  } else if (score >= 70) {
    grade = 'B';  gradeMsg = '안정적인 흐름 — 꾸준히 나아가면 됩니다';
    color = '#38bdf8'; // 파랑
  } else if (score >= 55) {
    grade = 'C';  gradeMsg = '에너지 보충 필요 — 무리하지 마세요';
    color = '#f87171'; // 빨강
  } else {
    grade = 'D';  gradeMsg = '회복이 우선 — 충분한 휴식을 취하세요';
    color = '#a78bfa'; // 보라
  }

  // ── 6. 점수 구성 설명 (사용자에게 보여줄 문장) ───────────
  var breakdown = '';
  var label = '';
  if (scanned) {
    label = 'CEI 통합 지수';
    var measuredCount = [
      bfd.bpm > 0, bfd.hrv > 0, bfd.fci > 0, bfd.bli > 0, tli > 0
    ].filter(Boolean).length;
    breakdown = [
      '🧬 생체(BAI) ' + bai + '점 × 40%',
      '🔮 역학(ILI) ' + ili + '점 × 35%',
      '🌌 공명 ' + resonanceScore + '점 × 25%',
      '→ 최종 CEI ' + cei + '점',
      '📡 실측 항목: ' + measuredCount + '개 측정 완료'
    ].join('\n');
  } else {
    label = 'ILI 역학 지수';
    breakdown = [
      '🔮 역학(ILI) ' + ili + '점',
      '→ 50개 역학 엔진 종합 점수',
      '💡 생체 스캔 완료 시 더 정밀한 CEI로 업그레이드됩니다'
    ].join('\n');
  }

  // ── 7. 결과 반환 ─────────────────────────────────────────
  return {
    score    : score,
    mode     : scanned ? 'CEI' : 'ILI',
    label    : label,
    grade    : grade,
    gradeMsg : gradeMsg,
    color    : color,
    ili      : ili,
    bai      : scanned ? bai : 0,
    cei      : cei,
    scanned  : scanned,
    breakdown: breakdown,
    // 개별 생체 수치도 포함 (팝업·카드에서 바로 사용 가능)
    bpm      : bfd.bpm  || 0,
    hrv      : bfd.hrv  || 0,
    fci      : bfd.fci  || 0,
    bli      : bfd.bli  || 0,
    tli      : (window.BS && window.BS.tongueData) ? (window.BS.tongueData.tliScore || 0) : 0
  };
};

function getMonthGanJiNASA(sunLon, y) {
  var lon = ((sunLon % 360) + 360) % 360;

  // 현재 월건 인덱스 (0=인월, 1=묘월 ... 11=축월)
  var monthIdx = 0;
  for (var i = 0; i < 12; i++) {
    var startLon = MONTH_START_LON[i];
    var endLon   = MONTH_START_LON[(i + 1) % 12];
    // 황도 0° 넘는 구간 처리 (285°→315° 사이)
    var inRange;
    if (startLon > endLon) {
      inRange = (lon >= startLon || lon < endLon);
    } else {
      inRange = (lon >= startLon && lon < endLon);
    }
    if (inRange) { monthIdx = i; break; }
  }

  // 월지 (지지)
  var monthJi = MONTH_JI_ORDER[monthIdx];

  // 월간 (천간) — 연간 기준 오자법
  // 甲己년→丙寅시작, 乙庚년→戊寅, 丙辛년→庚寅, 丁壬년→壬寅, 戊癸년→甲寅
  var yearGanIdx = ((y - 4) % 10 + 10) % 10;
  var monthGanBase = [2, 4, 6, 8, 0][yearGanIdx % 5]; // 인월 시작 천간 인덱스
  var monthGan = GANS[(monthGanBase + monthIdx) % 10];

  // 현재 절기 이름
  var termName = '';
  var minDiff = 360;
  SOLAR_TERMS_LON.forEach(function(t) {
    var diff = Math.abs(lon - t.lon);
    if (diff > 180) diff = 360 - diff;
    if (diff < minDiff) { minDiff = diff; termName = t.name; }
  });

  // 절기까지 남은 각도 (다음 절기까지)
  var nextTermLon = MONTH_START_LON[(monthIdx + 1) % 12];
  var remaining = nextTermLon - lon;
  if (remaining < 0) remaining += 360;
  var remainDays = Math.round(remaining / 360 * 365.25);

  return {
    gan: monthGan,
    ji: monthJi,
    termName: termName,
    monthIdx: monthIdx,
    remainDays: remainDays,
    sunLon: lon.toFixed(2),
    isNASA: true
  };
};

function getDayGanJiNASA(y, m, d) {
  var jd = julianDay(y, m, d);
  var gan = GANS[((jd % 10) + 10) % 10];
  var ji  = JIJIS[((jd % 12) + 12) % 12];
  // NASA 달 위상으로 일진 에너지 보정값 계산
  var moonBonus = 0;
  if (window._nasaPlanets && window._nasaPlanets.moon) {
    var moonLon = parseFloat(window._nasaPlanets.moon.lon || 0);
    var sunLon2  = window._nasaPlanets.sun ? parseFloat(window._nasaPlanets.sun.lon || 0) : 0;
    var phase    = ((moonLon - sunLon2) % 360 + 360) % 360;
    // 보름(180°) 근처 — 에너지 최고조
    moonBonus = Math.round(Math.sin(phase * Math.PI / 180) * 5);
  }
  return { gan: gan, ji: ji, moonBonus: moonBonus, isNASA: true };
};

