try{
window.tarotImgFile=function(id){
  id=+id; var B=_TAROT_IMG_BASE;
  if(isNaN(id)) return B+'0.jpeg';
  if(id<=22) return B+id+'.jpeg';
  var s,o;
  if(id<=36){s='wand';o=id-23;}
  else if(id<=50){s='cup';o=id-37;}
  else if(id<=64){s='sword';o=id-51;}
  else {s='pent';o=id-65;}
  var r=(o<=9)?String(o+1):['page','knight','queen','king'][o-10];
  return B+s+'_'+r+'.jpeg';
};
}catch(_e){}

function cgoFusionSelectSys(sysId) {
  // 같은 거 다시 탭 = 해제, 또는 null 명시 = 해제
  if (sysId === null || window._cgoFusionSelectedSys === sysId) {
    window._cgoFusionSelectedSys = null;
  } else {
    window._cgoFusionSelectedSys = sysId;
  }
  // 융합 페이지 재렌더링 (스크롤 위치 보존)
  var pop = document.getElementById('cgoFusionPopup');
  var scrollTop = pop ? pop.scrollTop : 0;
  if (typeof cgoFusionRender === 'function') cgoFusionRender();
  if (pop) {
    setTimeout(function(){ pop.scrollTop = scrollTop; }, 50);
  }
};

