function cgoFusionGuidePop(kind) {
  var ctx = window._cgoFusionCtx || {};
  var nbti = ctx.nbti || {};
  var card = ctx.card || {};
  var oh = ctx.oh || '목';
  var ili = ctx.ili || 70;
  var key1 = (card.key && card.key[0]) || '변화';
  var key2 = (card.key && card.key[1]) || '성장';
  var html = '';

  if (kind === 'do') {
    html =
      '<div style="font-size:11px;color:#34d399;letter-spacing:.14em;font-weight:800;margin-bottom:10px;">✓ 오늘 할 것 — 5문단 가이드</div>'+
      '<h3 style="font-size:16px;color:#f0e6c8;margin:0 0 12px;font-weight:900;">'+_oh_keyword(oh)+'의 에너지를 활용하라</h3>'+
      '<p style="margin:0 0 12px;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#34d399">① 핵심 행동:</b> '+oh+'오행의 핵심 키워드 "<b>'+_oh_keyword(oh)+'</b>"을 오늘 하루 의식적으로 실행하세요. '+(card.name||'카드')+' 카드의 "'+key1+'" 메시지가 같은 방향을 가리킵니다. 두 신호가 일치한다는 건 — 망설이지 말라는 뜻이에요.</p>'+
      '<p style="margin:0 0 12px;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#34d399">② 구체 행동 3가지:</b><br>• 오전 중 가장 미루고 있던 일 1개를 시작하세요 (15분만이라도)<br>• '+(nbti.type||'?')+'의 강점이 발휘되는 환경에 1시간 이상 노출되세요<br>• 오늘 하루 결정한 것 1개를 메모로 남기세요 (내일 ILI 보정 +2점)</p>'+
      '<p style="margin:0 0 12px;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#34d399">③ 시간대:</b> '+(({'목':'오전 5~9시','화':'정오 전후','토':'오전 9~11시','금':'오후 3~5시','수':'저녁 7~9시'})[oh])+' — 이 시간대에 중요한 행동을 배치하면 효과 +30%.</p>'+
      '<p style="margin:0 0 12px;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#34d399">④ ILI '+ili+'점 활용도:</b> '+(ili>=75?'에너지가 충분합니다. 계획한 모든 행동 실행 가능':ili>=60?'적정 에너지. 우선순위 1~2개에 집중':'에너지 부족. 가장 작은 행동 1개만 — 그것이 더 큰 효과')+'.</p>'+
      '<p style="margin:0;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#34d399">⑤ 보너스 효과:</b> 위 3가지를 모두 실행하면 — 내일의 통합 인생 지수(ILI)가 자연스럽게 +3~5점 상승합니다. 좋은 흐름이 누적되는 시작점이에요.</p>';
  }
  else if (kind === 'pause') {
    html =
      '<div style="font-size:11px;color:#0284c7;letter-spacing:.14em;font-weight:800;margin-bottom:10px;">⏸ 잠시 멈출 것 — 5문단 가이드</div>'+
      '<h3 style="font-size:16px;color:#f0e6c8;margin:0 0 12px;font-weight:900;">'+(card.name||'카드')+'이 경계하는 행동</h3>'+
      '<p style="margin:0 0 12px;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#0284c7">① 핵심 경계:</b> '+(card.name||'카드')+' 카드의 그림자 측면 — 이 카드의 에너지가 과하게 작동할 때 나오는 부작용을 오늘 특히 조심해야 합니다. "'+key1+'"이 너무 강하면 "'+key2+'"의 균형을 잃어요.</p>'+
      '<p style="margin:0 0 12px;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#0284c7">② 멈출 행동 3가지:</b><br>• 충동적인 큰 결정 (이메일·계약·투자 — 24시간 보류)<br>• '+((nbti.type&&nbti.type.indexOf('J')>=0)?'완벽주의에 빠지는 마무리 작업':'산만하게 새 일 시작')+'<br>• 감정적 메시지·SNS 글 (특히 ILI 60 이하인 날)</p>'+
      '<p style="margin:0 0 12px;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#0284c7">③ 시간대 주의:</b> '+(({'목':'오후 3~5시 (금극목 시간)','화':'오후 11시~오전 1시','토':'새벽 3~5시','금':'정오 전후','수':'오전 9~11시'})[oh])+' — 본성과 어긋나는 시간이라 큰 결정은 피하세요.</p>'+
      '<p style="margin:0 0 12px;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#0284c7">④ '+(nbti.type||'?')+' 그림자:</b> '+(((window._cgoFusionCtx||{}).info||{}).detail&&(window._cgoFusionCtx||{}).info.detail.weakness||'완벽주의·자기 소진')+' — 오늘 이 패턴이 발동되면 즉시 중단하고 휴식.</p>'+
      '<p style="margin:0;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#0284c7">⑤ 멈춤의 가치:</b> 멈출 줄 아는 사람이 진짜 강한 사람입니다. 오늘 이 3가지를 멈추면 — 내일 시작할 때 ILI가 +2~4점 회복되어 있을 거예요.</p>';
  }
  else if (kind === 'next') {
    html =
      '<div style="font-size:11px;color:#c4b5fd;letter-spacing:.14em;font-weight:800;margin-bottom:10px;">→ 다음 한 걸음 — 5문단 가이드</div>'+
      '<h3 style="font-size:16px;color:#f0e6c8;margin:0 0 12px;font-weight:900;">'+(nbti.type||'?')+' 성격에 맞는 다음 선택</h3>'+
      '<p style="margin:0 0 12px;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#c4b5fd">① 다음 단계의 본질:</b> 오늘의 행동이 내일·다음 주·다음 달로 이어지려면 — 지금 1개의 다음 단계를 명확히 정의해야 합니다. '+(nbti.type||'?')+' 유형은 '+((nbti.type&&nbti.type.indexOf('J')>=0)?'명확한 목표':'유연한 방향성')+' 안에서 가장 잘 움직여요.</p>'+
      '<p style="margin:0 0 12px;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#c4b5fd">② 구체 단계 3가지:</b><br>• 오늘 한 일 중 가장 효과적이었던 1가지를 내일도 반복<br>• 오늘 미룬 일 중 1개를 내일 오전으로 스케줄 고정<br>• 이번 주 안에 도달하고 싶은 작은 목표 1개 적기</p>'+
      '<p style="margin:0 0 12px;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#c4b5fd">③ '+(card.name||'카드')+' 카드의 다음:</b> "'+key1+'" 다음에 오는 흐름은 보통 "'+key2+'"입니다. 카드는 그 순서를 알려주는 지도예요. 지금 단계를 잘 마무리하면, 다음 단계가 자연스럽게 열립니다.</p>'+
      '<p style="margin:0 0 12px;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#c4b5fd">④ '+oh+'오행 흐름:</b> '+(({'목':'씨앗 → 새싹 → 줄기 → 잎','화':'점화 → 활활 → 절정 → 잿불','토':'기반 → 다지기 → 결합 → 안정','금':'결정 → 단단해짐 → 다듬기 → 완성','수':'스며들기 → 모이기 → 깊어짐 → 흐름'})[oh])+' — 지금 어느 단계에 있는지 살펴보세요.</p>'+
      '<p style="margin:0;line-height:1.95;font-size:12.5px;color:rgba(240,220,160,.88);"><b style="color:#c4b5fd">⑤ 7일 후 체크:</b> 일주일 후 다시 융합 분석을 받아보세요. 다른 카드가 나오고, ILI 점수가 변해 있을 거예요. 그 변화의 방향이 — 지금 시작한 다음 단계가 잘 가고 있는지의 답입니다.</p>';
  }

  _cgoFusionShowPopup(html);
};

function cgoFusionChatSend() {
  var _input = document.getElementById('cgoFusionChatInput');
  var _msgs = document.getElementById('cgoFusionChatMsgs');
  if (!_input || !_msgs) return;
  var _txt = (_input.value || '').trim();
  if (!_txt) return;
  _input.value = '';

  // 사용자 메시지 추가
  _msgs.innerHTML += '<div style="margin-top:10px;text-align:right;"><span style="display:inline-block;padding:8px 12px;background:rgba(212,168,67,.12);border:1px solid rgba(212,168,67,.3);border-radius:12px 12px 2px 12px;color:#f0e6c8;font-size:12px;max-width:85%;text-align:left;">'+_txt+'</span></div>';
  _msgs.scrollTop = _msgs.scrollHeight;

  // AI 호출 (기존 qtCallAI 함수 재사용 — 융합 컨텍스트 추가)
  var _nbti = window._mspResult || {};
  var _card = (window._qt && window._qt.selectedCard) || {};
  var _r = window.calcResult || {};
  var _oh = _r.domOh || '목';
  var _ctxMsg = '[융합 분석 컨텍스트] 타로:'+(_card.name||'?')+' / NBTI:'+(_nbti.type||'?')+' / 오행:'+_oh+' / ILI:'+(_r.ili||70)+'\n\n질문: '+_txt;

  // 로딩 표시
  var _loadingId = 'cgoFusionLoading_' + Date.now();
  _msgs.innerHTML += '<div id="'+_loadingId+'" style="margin-top:10px;"><span style="display:inline-block;padding:8px 12px;background:rgba(168,85,247,.08);border:1px solid rgba(168,85,247,.2);border-radius:12px 12px 12px 2px;color:rgba(196,181,253,.7);font-size:12px;">분석 중...</span></div>';
  _msgs.scrollTop = _msgs.scrollHeight;

  if (typeof qtCallAI === 'function') {
    qtCallAI(_ctxMsg, function(reply){
      var _l = document.getElementById(_loadingId);
      if (_l) _l.parentNode.removeChild(_l);
      _msgs.innerHTML += '<div style="margin-top:10px;"><span style="display:inline-block;padding:10px 14px;background:rgba(168,85,247,.1);border:1px solid rgba(168,85,247,.25);border-radius:12px 12px 12px 2px;color:rgba(240,220,160,.9);font-size:12px;line-height:1.85;max-width:90%;">'+(reply||'AI 응답을 받지 못했습니다.')+'</span></div>';
      _msgs.scrollTop = _msgs.scrollHeight;
    });
  } else {
    var _l = document.getElementById(_loadingId);
    if (_l) _l.parentNode.removeChild(_l);
    _msgs.innerHTML += '<div style="margin-top:10px;color:rgba(248,113,113,.7);font-size:11px;">AI 채팅 준비 중입니다.</div>';
  }
};

