function setSbTag(id,val,val2,color){
    var t=document.getElementById('sbt-'+id), v=document.getElementById('sbv-'+id);
    if(!t||!v)return;
    setTimeout(function(){
      v.textContent=val2||val;
      v.style.color=color;
      t.classList.add('on');
      t.style.background=color.replace('var(--','').replace(')','')==='' ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.2)';
      t.style.borderColor=color;
    },300);
  };

function gradeInfo(n){
  if(n>=85)return{grade:'매우 좋음',desc:'하늘과 당신이 가장 잘 맞닿아 있는 날이에요 ✨',idx:4};
  if(n>=70)return{grade:'좋음',desc:'에너지가 고르게 흐르고 있어요. 믿고 나아가세요 🌙',idx:3};
  if(n>=55)return{grade:'보통',desc:'차분하게 균형을 유지하는 날이에요.',idx:2};
  if(n>=40)return{grade:'주의',desc:'오늘은 자신을 조금 더 돌봐 주세요 💛',idx:1};
  return{grade:'재충전',desc:'에너지를 모아두는 날이에요. 잘 쉬는 것이 내일의 힘이 돼요.',idx:0};
};

function animateNum(id,target){
  var el=document.getElementById(id);
  if(!el)return;
  var start=0,dur=1200,startTime=null;
  function step(ts){
    if(!startTime)startTime=ts;
    var progress=Math.min((ts-startTime)/dur,1);
    el.textContent=Math.floor(start+(target-start)*progress);
    if(progress<1)requestAnimationFrame(step);
    else el.textContent=target;
  }
  requestAnimationFrame(step);
};

function drawTrend(){
  var svg=document.getElementById('trendSvg');
  if(!svg)return;
  var base=appState.ili||70;
  // ★ C-35 헌법 §V.5.5: Math.random 폐기 → 날짜 결정론 시드 (같은 날 = 같은 값)
  var _td7 = (new Date().getDate()*7 + (appState.userY||1980))%100;
  var vals=Array.from({length:7},function(_,i){
    var seed7 = (_td7 + i*23 + base*3) % 11;
    return Math.max(40,Math.min(95,base + seed7 - 5 + i)); // 헌법 95 캡
  });
  vals[6]=base;
  var w=600,h=80,pad=20;
  var minV=Math.min.apply(null,vals)-5,maxV=Math.max.apply(null,vals)+5;
  var pts=vals.map(function(v,i){
    var x=pad+i*(w-2*pad)/6;
    var y=h-pad-(v-minV)/(maxV-minV)*(h-2*pad);
    return x+','+y;
  });
  // SVG 전체 교체 방식으로 insertBefore 오류 방지
  var inner=
    '<defs><linearGradient id="tg2" x1="0" y1="0" x2="0" y2="1">'+
    '<stop offset="0%" stop-color="#d4a843" stop-opacity=".2"/>'+
    '<stop offset="100%" stop-color="#d4a843" stop-opacity="0"/></linearGradient></defs>'+
    '<polygon points="'+pts[0].split(',')[0]+','+h+' '+pts.join(' ')+' '+pts[6].split(',')[0]+','+h+'" fill="url(#tg2)"/>'+
    '<polyline points="'+pts.join(' ')+'" fill="none" stroke="#d4a843" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>'+
    vals.map(function(v,i){
      var pt=pts[i].split(',');
      return '<circle cx="'+pt[0]+'" cy="'+pt[1]+'" r="3" fill="#d4a843"/>'+
      '<text x="'+pt[0]+'" y="'+(parseFloat(pt[1])-7)+'" text-anchor="middle" font-size="9" fill="#94a3b8">'+v+'</text>';
    }).join('');
  try{ svg.innerHTML=inner; }
  catch(e){
    // fallback: 폴리라인만 그리기
    var simple='<polyline points="'+pts.join(' ')+'" fill="none" stroke="#d4a843" stroke-width="2"/>'+
    vals.map(function(v,i){var pt=pts[i].split(',');return '<circle cx="'+pt[0]+'" cy="'+pt[1]+'" r="3" fill="#d4a843"/>';}).join('');
    try{ svg.innerHTML=simple; }catch(e2){}
  }
};

function hltReset(){
  window._hltAnalyzed = false; // 분석 플래그 초기화
  clearInterval(_HV.bTimer);clearInterval(_HV.tTimer);
  clearInterval(_HV.tmpTimer);clearInterval(_HV.visTimer);clearInterval(_HV.dotTimer);
  _HV={bDone:false,tDone:false,tmpDone:false,visDone:false,
    bScore:0,tScore:0,tmpScore:0,v4:0,v5:0,
    bTimer:null,tTimer:null,tmpTimer:null,visTimer:null,dotTimer:null,
    bPhase:0,bSec:0,bCycle:0,scores:new Array(18).fill(0)};
  var defs=['측정 대기','스캔 대기','측정 대기','얼굴 12궁','생명선·건강선','오행 불균형','질액궁 분석','에너지 흐름','현재 운때','64괘 조언','수 진동 에너지','이름 음가 파동'];
  for(var i=1;i<=12;i++){
    var sc=_g('hlt-c'+i+'s');if(sc)sc.textContent='--';
    var b=_g('hlt-c'+i+'b');if(b)b.style.width='0%';
    var d=_g('hlt-c'+i+'d');if(d)d.textContent=defs[i-1];
    var c=_g('hc'+i);if(c)c.classList.remove('done');
  }
  // STEP1
  var bnum=_g('hlt-bnum');if(bnum){bnum.textContent='--';bnum.style.color='#38bdf8';}
  var blbl=_g('hlt-blbl');if(blbl){blbl.textContent=_cgoT('대기');blbl.style.color='rgba(56,189,248,.5)';}
  var bph=_g('hlt-bphase');if(bph){bph.textContent=_cgoT('시작 버튼을 눌러주세요');bph.style.color='#e2e8f0';}
  var bsb=_g('hlt-bscore-box');if(bsb)bsb.style.display='none';
  var bring=_g('hlt-bring');if(bring){bring.style.strokeDashoffset='219.9';bring.style.stroke='#38bdf8';}
  var bbtn=_g('hlt-bbtn');if(bbtn){bbtn.textContent=_cgoT('▶ 호흡 시작');bbtn.disabled=false;}
  // STEP2
  var tp=_g('hlt-tprog');if(tp)tp.style.display='none';
  var tb=_g('hlt-tbar');if(tb)tb.style.width='0%';
  ['tc-color-v','tc-coat-v','tc-shape-v'].forEach(function(id){var e=_g(id);if(e)e.textContent=_cgoT('대기');});
  var tbtn=_g('hlt-tbtn');if(tbtn){tbtn.textContent=_cgoT('📷 혀 스캔 시작');tbtn.disabled=false;}
  for(var j=1;j<=10;j++){var d2=_g('hvd'+j);if(d2){d2.style.background='rgba(248,113,113,.15)';d2.style.transform='scale(1)';d2.style.boxShadow='none';}}
  // STEP3
  var tv=_g('hlt-tempval');if(tv){tv.textContent='--';}
  var ki=_g('hlt-kival');if(ki)ki.textContent='--';
  var en=_g('hlt-enval');if(en)en.textContent='--';
  var ts=_g('hlt-temp-status');if(ts)ts.textContent=_cgoT('스마트폰을 양손으로 꽉 쥐어주세요');
  var tring=_g('hlt-tcircle');if(tring){tring.style.strokeDashoffset='232.5';tring.style.stroke='#fbbf24';}
  var tempbtn=_g('hlt-tempbtn');if(tempbtn){tempbtn.textContent=_cgoT('🌡️ 온도 리듬 체크 시작');tempbtn.disabled=false;}
  // STEP4
  var fs=_g('hlt-facesc');if(fs)fs.textContent='--';
  var ps=_g('hlt-palmsc');if(ps)ps.textContent='--';
  var fst=_g('hlt-facest');if(fst)fst.textContent=_cgoT('대기중');
  var pst=_g('hlt-palmst');if(pst)pst.textContent=_cgoT('대기중');
  var vbtn=_g('hlt-visbtn');
  if(vbtn){
    vbtn.textContent=_cgoT('🔬 비전 분석 시작');
    vbtn.disabled=false;
    vbtn.style.background='';
    vbtn.style.color='';
    vbtn.style.borderColor='';
    vbtn.style.cursor='';
  }
  // 얼굴/손금 박스 초기화
  var fbox2=_g('hlt-facebox');
  if(fbox2){ fbox2.style.background='rgba(167,139,250,.06)'; fbox2.style.borderColor='rgba(167,139,250,.25)'; }
  var pbox2=_g('hlt-palmbox');
  if(pbox2){ pbox2.style.background='rgba(244,114,182,.06)'; pbox2.style.borderColor='rgba(244,114,182,.25)'; }
  var fst2=_g('hlt-facest'); if(fst2) fst2.textContent=_cgoT('대기중');
  var pst2=_g('hlt-palmst'); if(pst2) pst2.textContent=_cgoT('대기중');
  var fsc2=_g('hlt-facesc'); if(fsc2) fsc2.textContent='--';
  var psc2=_g('hlt-palmsc'); if(psc2) psc2.textContent='--';
  if(typeof _HV !== 'undefined'){ _HV.visDone1=false; _HV.visDone2=false; }
  var fb=_g('hlt-facebox');if(fb){fb.style.background='rgba(167,139,250,.06)';fb.style.borderColor='rgba(167,139,250,.25)';}
  var pb=_g('hlt-palmbox');if(pb){pb.style.background='rgba(244,114,182,.06)';pb.style.borderColor='rgba(244,114,182,.25)';}
  var res=_g('hlt-result');if(res)res.style.display='none';
};

