function tarotCard(card,label,ci){
    var pc=card.pos?'tarot-upright':'tarot-reversed';
    var pl=card.pos?'정방향 ▲':'역방향 ▽';
    return '<div class="tarot-card" onclick="txOpen('+ci+')" title="탭하면 상세 해석">'+
      '<div style="font-size:9px;color:rgba(212,168,67,.55);margin-bottom:3px">👆 탭하여 해석</div>'+
      '<div class="tarot-card-icon">'+card.icon+'</div>'+
      '<div class="tarot-card-name" style="font-size:9px;color:var(--text-3)">'+label+'</div>'+
      '<div class="tarot-card-title">'+_cgoTV(card.kr,card.name)+'</div>'+
      '<div class="tarot-card-pos '+pc+'">'+pl+'</div>'+
      '<div style="font-size:10px;color:var(--text-3);margin-top:5px;line-height:1.4">'+_cgoT(card.adv).substring(0,28)+'</div>'+
    '</div>';
  };

function txOpen(ci) {
  var cards = window._txCards;
  if (!cards || !cards[ci]) return;
  var c = cards[ci];
  var d = TAROT_DB[c.id] || TAROT_DB[c.icon] || {
    el:'우주 에너지', planet:'신비의 행성', num:'∞',
    up:c.adv, rv:'에너지가 내면으로 향합니다. 자기 성찰의 시간.',
    love_up:'사랑의 에너지가 활성화됩니다. 마음을 열고 받아들이세요.',
    love_rv:'내면의 감정을 정리하는 시간이 필요합니다.',
    biz_up:'이 카드의 에너지를 업무에 적극 활용하세요.',
    biz_rv:'방향 재설정이 필요한 시기. 멈추고 재검토하세요.',
    adv_up:c.adv, adv_rv:'내면을 들여다보는 시간. 외면보다 내면에 집중하세요.'
  };

  var labels = ['과거·원인','현재·상황','미래·결과'];
  var rv = !c.pos;
  var meaning = rv ? d.rv : d.up;
  var love    = rv ? d.love_rv : d.love_up;
  var biz     = rv ? d.biz_rv  : d.biz_up;
  var adv     = rv ? d.adv_rv  : d.adv_up;

  document.getElementById('txTitle').textContent = c.kr + ' · ' + c.name;
  document.getElementById('txSub').textContent = labels[ci] + ' — ' + (rv ? '역방향 ▽' : '정방향 ▲');

  var icoHtml = rv
    ? '<span style="display:inline-block;transform:rotate(180deg)">'+c.icon+'</span>'
    : c.icon;

  document.getElementById('txBody').innerHTML =
    '<div class="tx-card-box'+(rv?' rev':'')+'">'+
      '<div class="tx-big-ico">'+icoHtml+'</div>'+
      '<div style="font-size:11px;color:rgba(240,230,200,0.8);margin-bottom:4px">'+labels[ci]+'</div>'+
      '<div style="font-size:22px;font-weight:700;color:#f0e6c8;margin-bottom:4px">'+c.kr+'</div>'+
      '<div style="font-size:12px;color:rgba(240,230,200,0.85);margin-bottom:10px">'+c.name+'</div>'+
      '<span class="tx-badge '+(rv?'tx-rev':'tx-up')+'">'+(rv?'역방향 ▽':'정방향 ▲')+'</span>'+
    '</div>'+
    '<div class="tx-meta">'+
      '<span>원소: '+d.el+'</span>'+
      '<span>행성: '+d.planet+'</span>'+
      '<span>번호: '+d.num+'</span>'+
    '</div>'+
    '<div class="ix-sec"><div class="ix-sec-t">🔮 카드의 메시지</div>'+
      '<div class="tx-block">'+meaning+'</div></div>'+
    '<div class="ix-sec"><div class="ix-sec-t">🌟 분야별 해석</div>'+
      '<div class="ix-row"><div class="ix-row-ico">💕</div><div class="ix-row-txt"><strong style="color:rgba(240,100,150,.8)">사랑·관계</strong><br>'+love+'</div></div>'+
      '<div class="ix-row"><div class="ix-row-ico">💼</div><div class="ix-row-txt"><strong style="color:rgba(212,168,67,.8)">직업·사업</strong><br>'+biz+'</div></div></div>'+
    '<div class="ix-sec" style="border-color:rgba(212,168,67,.2)"><div class="ix-sec-t">💡 오늘의 조언</div>'+
      '<div class="tx-block gold" style="font-size:14px;font-style:italic">'+adv+'</div></div>'+
    '<div style="text-align:center;margin-top:16px;font-size:11px;color:rgba(255,255,255,.2)">🃏 타로 · 서양 신비주의의 지혜</div>';

  document.getElementById('txOverlay').classList.add('open');
  document.getElementById('txPopup').classList.add('open');
  document.body.style.overflow = 'hidden';
  _cgoTransPopup('txBody');
};

try{
window._cgoTV = function(ko, en){
  try{
    var L = (window._cgoKeyLang ? window._cgoKeyLang() : window._LANG) || 'en';
    if(L === 'ko') return ko;
    if(ko != null && typeof _cgoT === 'function'){
      var v = _cgoT(String(ko));
      if(v && v !== String(ko) && !/[\uac00-\ud7a3]/.test(v)) return v;
    }
    return (en !== undefined && en !== null && en !== '') ? en : ko;
  }catch(e){ return en != null ? en : ko; }
};
}catch(_e){}

