  var GMD_DIR_DETAIL={
    坎:{name:'감(坎)',element:'水·물',body:'신장·방광·귀·혈액',career:'지혜·탐구·철학·의료',avoid:'과음·무리한 야간활동',tip:'수기(水氣)가 강한 방위. 깊이 생각해야 할 일, 연구, 계획에 적합. 감정 기복에 주의.'},
    艮:{name:'간(艮)',element:'土·흙(산)',body:'등·손·비장·코',career:'부동산·축적·산업·농업',avoid:'고집·변화거부',tip:'정지와 축적의 에너지. 새로운 시작보다 현재 것을 다지는 데 최적. 인내심이 관건.'},
    震:{name:'진(震)',element:'木·나무',body:'발·신경',career:'창업·발명·스포츠·혁신',avoid:'충동적 결정·사고',tip:'동적 에너지의 방위. 새 프로젝트 시작, 운동, 창의적 도전에 최고. 서두르지 말 것.'},
    巽:{name:'손(巽)',element:'木·바람',body:'정돈 에너지·허벅지·호흡기',career:'무역·유통·언론·외교',avoid:'우유부단·소문',tip:'교류와 소통의 에너지. 협상, 여행, 네트워킹에 유리. 정보 취합·전달이 핵심.'},
    離:{name:'리(離)',element:'火·불',body:'심장·눈·긴장·뇌',career:'예술·홍보·명예·교육',avoid:'과열·급한 성격',tip:'빛과 명예의 방위. 발표, 시험, 사교 활동에 이상적. 감정 조절이 중요.'},
    坤:{name:'곤(坤)',element:'土·땅',body:'위·비·근육·복부',career:'부동산·농업·돌봄·복지',avoid:'게으름·의존',tip:'포용과 양육의 에너지. 팀 협력, 관계 회복, 내실 다지기에 최적.'},
    兌:{name:'태(兌)',element:'金·금속',body:'폐·입·치아·혀',career:'금융·언변·협상·음악',avoid:'구설수·과한 말',tip:'기쁨과 소통의 에너지. 협상, 발표, 고객 응대에 탁월. 말을 조심할 것.'},
    乾:{name:'건(乾)',element:'金·하늘',body:'머리·폐·뼈·대장',career:'리더십·관리·법률·경영',avoid:'독선·과도한 자존심',tip:'하늘의 에너지. 결단, 리더십, 중요한 의사결정에 최적의 방위.'}
  };
