function tarotRp(card,label){
    var pc=card.pos?'tarot-upright':'tarot-reversed';
    var pl=card.pos?'정방향 ▲':'역방향 ▽';
    return '<div class="tarot-card"><div class="tarot-card-icon">'+card.icon+'</div><div class="tarot-card-name" style="font-size:9px;color:var(--text-3)">'+label+'</div><div class="tarot-card-title">'+_cgoTV(card.kr,card.name)+'</div><div class="tarot-card-pos '+pc+'">'+pl+'</div><div style="font-size:10px;color:var(--text-3);margin-top:5px;line-height:1.4">'+_cgoT(card.adv).substring(0,90)+'</div></div>';
  };

function _cgoVisionClose(){
  var ov = document.getElementById('cgo-vision-ov');
  if(ov) ov.style.display = 'none';
  var v = document.getElementById('cgo-vision-video');
  if(v && v.srcObject){ v.srcObject.getTracks().forEach(function(t){t.stop();}); v.srcObject=null; }
  if(window._cgoVisionScanTimer){ clearInterval(window._cgoVisionScanTimer); window._cgoVisionScanTimer=null; }
  // ★ C-35 — 닫을 때 전역 안전망 호출 (다른 video/audio도 확실히 정화)
  try{ _cgoForceStopAllMedia(); }catch(e){}
  if(window._cgoPrivacyShutdownTimer){ clearTimeout(window._cgoPrivacyShutdownTimer); window._cgoPrivacyShutdownTimer=null; }
  try{ if(window._cgoScanOrigin==='rppg'){ window._cgoScanOrigin=null; setTimeout(function(){ if(typeof cgoLaunchRppg==='function') cgoLaunchRppg(); }, 200); } }catch(e){}
};

function _cgoVisionStartScan(){
  var startBtn = document.getElementById('cgo-vision-start');
  if(startBtn) startBtn.style.display = 'none';
  var scanLine = document.getElementById('cgo-vision-scanline');
  if(scanLine) scanLine.style.display = 'block';
  var timerBox = document.getElementById('cgo-vision-timer-box');
  if(timerBox) timerBox.style.display = 'block';
  var statusEl = document.getElementById('cgo-vision-status');
  var progress = document.getElementById('cgo-vision-progress');
  var timerEl = document.getElementById('cgo-vision-timer');
  var v = document.getElementById('cgo-vision-video');

  var _mode = window._cgoVisionMode;
  var total = (_mode === 'tongue') ? 15 : 33;
  var remaining = total;
  if(timerEl) timerEl.textContent = remaining;

  // ★ 피사체 감지용 캔버스 (64x64 저해상도)
  var _dc = document.createElement('canvas');
  _dc.width = 64; _dc.height = 64;
  var _dx = _dc.getContext('2d', { willReadFrequently: true });

  function _hasSubject(){
    if(!v || !v.srcObject || v.readyState < 2) return false;
    try {
      var sw = v.videoWidth * 0.5, sh = v.videoHeight * 0.5;
      var sx = (v.videoWidth - sw) / 2, sy = (v.videoHeight - sh) / 2;
      _dx.drawImage(v, sx, sy, sw, sh, 0, 0, 64, 64);
      var d = _dx.getImageData(0, 0, 64, 64).data;
      var skinCount = 0, total = 0;
      for(var y=8; y<56; y++){
        for(var x=8; x<56; x++){
          var idx=(y*64+x)*4;
          var r2=d[idx], g=d[idx+1], b=d[idx+2];
          // 피부색 범위 (얼굴/손 공통): RGB 기반 피부 감지
          // 조건: R>95, G>40, B>20, R>G, R>B, R-G>15, R-B>15
          var isSkin = (r2>80 && g>40 && b>20 && r2>g && r2>b && (r2-g)>10);
          if(isSkin) skinCount++;
          total++;
        }
      }
      // 피사체가 화면 중앙을 충분히 채워야 통과 (관상·혀와 동일 원칙: 대상 없으면 멈춤)
      // ★ 손금은 후면 카메라라 책상·벽·옷 같은 베이지 배경을 살색으로 오인하기 쉬움 →
      //   손바닥이 확실히 화면을 채울 때만 통과하도록 임계 강화 (관상·혀처럼 동작시키기)
      var _skinThr = (window._cgoVisionMode === 'palm') ? 0.40 : 0.20;
      return (skinCount / total) > _skinThr;
    } catch(e){ return false; }
  }

  var mode = window._cgoVisionMode;
  var _vL=(window._LANG&&window._LANG!=='ko');
  var guideMsg = mode==='face'
    ? (_vL?'Line your face up with the on-screen guide':'얼굴을 화면 가이드에 맞춰주세요')
    : mode==='tongue'
    ? (_vL?'Bring your tongue close to the camera':'혀를 카메라에 가까이 보여주세요')
    : (_vL?'Spread your palm to fill the screen':'손바닥을 화면 가득 펼쳐주세요');

  window._cgoVisionScanTimer = setInterval(function(){
    if(!_hasSubject()){
      // 피사체 없음 → 타이머 멈춤
      if(scanLine) scanLine.style.animationPlayState = 'paused';
      if(statusEl) statusEl.textContent = '⚠️ ' + guideMsg;
      return;
    }
    // 피사체 감지됨 → 타이머 진행
    if(scanLine) scanLine.style.animationPlayState = 'running';
    remaining--;
    if(timerEl) timerEl.textContent = remaining;
    if(progress) progress.style.width = Math.round((total-remaining)/total*100) + '%';
    if(statusEl) statusEl.textContent = _cgoT('✅ 감지됨 — 움직이지 마세요 (')+ remaining +'초)';

    if(remaining <= 0){
      clearInterval(window._cgoVisionScanTimer);
      window._cgoVisionScanTimer = null;
      if(scanLine) scanLine.style.display = 'none';
      var doneEl = document.getElementById('cgo-vision-done');
      if(doneEl){ doneEl.style.display = 'flex'; }
      setTimeout(function(){ _cgoVisionShoot(); }, 800);
    }
  }, 1000);
};

try{
window._cgoTier = function(){
  try{
    if(window._cgoUnlimited) return 'master';
    var mo=false; try{ mo=localStorage.getItem('cgo_master_on')==='1'; }catch(e){}
    if(mo) return 'master';
    var paid=false; try{ paid=localStorage.getItem('cgo_paid')==='1'; }catch(e){}
    if(paid) return 'paid';
    try{ var tr=JSON.parse(localStorage.getItem('cgo_trial')||'null');
      if(tr && tr.start){ var days=tr.days||3; if(Date.now()-tr.start < days*86400000) return 'paid'; } }catch(e){}
    var su=false; try{ su=!!localStorage.getItem('cgo_signup'); }catch(e){}
    if(su) return 'free';
    return 'guest';
  }catch(e){ return 'free'; }  // 오류 시 막지도 열지도 않는 안전 기본값
};
}catch(_e){}

