  var level = ili >= 80 ? 'high' : ili >= 60 ? 'mid' : 'low';
  var _en=(window._LANG&&window._LANG!=='ko');
  var _src=_en?_FAMILY_ILI_MSG_EN:_FAMILY_ILI_MSG;
  var db = member.isSelf ? _src.self : (_src[oh] || _src['토']);
  return db[level] || (_en?'Monitoring energy flow.':'에너지 흐름을 모니터링 중입니다.');
